function bookFigureLink(f){const map={
 '4.1':['4/structure','shoot','新梢部位标注'], '4.2':['6/pruning','training-comparison','头状短枝的冬夏对照'], '4.3':['6/pruning','training-comparison','头状替换长枝的冬夏对照'], '4.4':['6/pruning','training-comparison','主蔓短枝的冬夏对照'], '4.5':['4/grafting','graft-methods','室内嫁接与接口保护'], '4.6':['4/grafting','graft-methods','田间换接保留的结构'],
 '5.1':['5/needs','needs','五个生长条件'], '5.2':['5/heat','latitude','纬度与能量分布'], '5.3':['5/heat','stone-heat','土壤及石块吸热、放热；梯田见正文'], '5.4':['5/heat','frost','低温受害对象；防霜工具机制见正文'], '5.5':['5/heat','site','坡面排冷与局地气候'], '5.6':['5/water','irrigation','三种灌溉供水路径'], '5.7':['6/pests','nets','防雹网与防鸟网的区别'], '5.8':['5/soil','chlorosis','黄化与叶片功能'],
 '6.1':['6/establish','new-vines','幼藤套管、支撑与供水设施'], '6.2':['6/cycle','annual-cycle','阶段顺序、月份与作业表'], '6.3':['6/pruning','training-comparison','三种结构冬夏对照，Sylvoz 按讲义单列'], '6.4':['6/density','density','低密度平面示意；炎热干旱案例见正文'], '6.5':['6/density','density','密度与竞争示意；温和多雨案例见正文'], '6.6':['6/pests','nets','果区防鸟网'], '6.7':['6/harvest','harvest-methods','机械采收果粒，果梗通常留藤'], '6.8':['6/harvest','harvest-methods','人工保留完整果串']
 };const v=map[f[1]];return v?`<a href="#read/${v[0]}/study-${v[1]}">${v[2]} ↗</a>`:bookPageLinks(f[2]);}
